        <p className="leading-[normal] mb-0">If ‘Select the category the Near Miss most relates to’ is “Auto – Near Miss” then show ‘Was this a Near Miss between two DART vehicles’, ‘Other vehicle #2 type’, ‘Other vehicle #2 action’</p>
