        <p className="leading-[normal] mb-0">Elseif ‘Pedestrian Type’ is ‘Using Mirco Mobility’ then ‘Pedestrian Action’ should show ‘Going Straight’, ‘Making a left turn’, ‘Making a right turn’, ‘Going backwards’, ‘Changing Lanes’, ‘Stopped’, ‘Negotiating a curve’</p>
