        <p className="leading-[normal] mb-0">ElseIf ‘Select the category the Near Miss most relates to’ is “Near Miss” is ‘Auto – Near Miss’, then do not show “Number of pedestrians Near Miss (Close Calls), Pedestrian Type”, “Pedestrian Action”</p>
